Object.assign(dutchMessages,{'Choose a boarding stop':'Kies een instaphalte','Choose a stop or use Correct location to set your starting point.':'Kies een halte of gebruik Locatie corrigeren om je vertrekpunt in te stellen.','Tap another stop to see its routes.':'Tik op een andere halte om de lijnen te bekijken.','Choose your city':'Kies je stad','No supported network here':'Hier is geen ondersteund netwerk','Choose a network or import a GTFS ZIP to load its stops and timetable.':'Kies een netwerk of importeer een GTFS-ZIP om de haltes en dienstregeling te laden.','No fresh GPS positions for this selection.':'Geen recente GPS-posities voor deze selectie.','No matching bus numbers.':'Geen overeenkomstige busnummers.','All bus lines':'Alle buslijnen','Change network':'Netwerk wijzigen'});
const lookup=new Map(Object.entries(dutchMessages).map(([k,v])=>[k.toLowerCase(),v]));
const t=s=>dutchMessages[s]||lookup.get(s.toLowerCase())||s;
const rules=[
 [/^(.+) · manual location$/i,m=>`${m[1]} · handmatige locatie`],
 [/^Official announcements and service notices for (.+)\.$/i,m=>`Officiële berichten en reismeldingen voor ${m[1]}.`],
 [/^Change network · (.+)$/i,m=>`Netwerk wijzigen · ${m[1]}`],
 [/^No fresh GPS positions for this selection\.$/i,()=> 'Geen recente GPS-posities voor deze selectie.'],
 [/^(\d+) minutes$/i,m=>`${m[1]} minuten`],
 [/^YOUR JOURNEY · STEP (\d+) OF (\d+)$/i,m=>`JE REIS · STAP ${m[1]} VAN ${m[2]}`],
 [/^Next: (.+?) → ~(.+?) Checked (\d{1,2}:\d{2})$/i,m=>`Volgende: ${m[1]} → ~${m[2]} Gecontroleerd ${m[3]}`],
 [/^Checked (\d{1,2}:\d{2})$/i,m=>`Gecontroleerd ${m[1]}`],
 [/^(Arrival|Arrive|Leave|Scheduled|Timetable prediction · arrive) (~?\d{1,2}:\d{2}(?: · \d{1,2} [A-Za-z]+)?)$/i,m=>`${t(m[1])} ${m[2]}`],
 [/^Timetable prediction · arrive ~(.*)$/i,m=>`Schatting volgens dienstregeling · aankomst ~${m[1]}`],
 [/^Arrive by (.+?) · (\d+(?:[.,]\d+)?) min (late|spare)$/i,m=>`Aankomen vóór ${m[1]} · ${m[2]} min ${m[3]==='late'?'te laat':'over'}`],
 [/^Estimated arrival ~(.*?)\. Find another journey\.$/i,m=>`Geschatte aankomst ~${m[1]}. Zoek een andere reis.`],
 [/^(\d+(?:[.,]\d+)?) min (spare|short|late|before your deadline)$/i,m=>`${m[1]} min ${{spare:'over',short:'tekort',late:'te laat','before your deadline':'vóór je gewenste aankomsttijd'}[m[2].toLowerCase()]}`],
 [/^(\d+(?:[.,]\d+)?) min (spare|short) after walking and your transfer buffer\.$/i,m=>`${m[1]} min ${m[2]==='spare'?'over':'tekort'} na het lopen en je overstapmarge.`],
 [/^(\d+(?:[.,]\d+)?) min walking \+ (\d+(?:[.,]\d+)?) min transfer buffer$/i,m=>`${m[1]} min lopen + ${m[2]} min overstapmarge`],
 [/^\((\d+(?:[.,]\d+)?) min\) \+ (\d+(?:[.,]\d+)?) min minimum transfer time$/i,m=>`(${m[1]} min) + ${m[2]} min minimale overstaptijd`],
 [/^(\d+(?:[.,]\d+)?) min between buses, minus walking and your buffer\.$/i,m=>`${m[1]} min tussen bussen, na aftrek van lopen en je marge.`],
 [/^(\d+(?:[.,]\d+)?) min(?: (walking|transfer buffer|minimum transfer time|transfer time))?$/i,m=>`${m[1]} min${m[2]?' '+t(m[2]):''}`],
 [/^(\d+(?:[.,]\d+)?) (transfers|stops)$/i,m=>`${m[1]} ${t(m[2]).toLowerCase()}`],
 [/^(~?\d+(?:[.,]\d+)? m|\d+(?:[.,]\d+)? km\/h) walking$/i,m=>`${m[1]} lopen`],
 [/^(fastest|fewest transfers|least walking|latest departure) first\.$/i,m=>`${t(m[1])} eerst.`],
 [/^Bus ((?=[\dA-Za-zА-Яа-я/-]*\d)[\dA-Za-zА-Яа-я/-]+)( · .+)?$/i,m=>`Bus ${m[1]}${m[2]||''}`],
 [/^(Bus stop|Stop) ([\dA-Za-z/-]+)$/i,m=>`${t(m[1])} ${m[2]}`],
 [/^(Walk to|Head to|Continue to|Get off at|Board at|To) (.+)$/i,m=>`${t(m[1])} ${m[2]==='your destination'?t(m[2]):m[2]}`],
 [/^Change buses at (.+)$/i,m=>`Overstappen bij ${m[1]}`],
 [/^Board (\d{1,2}:\d{2}(?: · \d{1,2} [A-Za-z]+)?) at (.+)$/i,m=>`Instappen om ${m[1]} bij ${m[2]}`],
 [/^Walk (~?\d+ m)(.*)$/i,m=>`Loop ${m[1]}${m[2]?translateDutch(m[2]):''}`],
 [/^Simpler alternative: (\d+) transfers · arrive ~(.*)$/i,m=>`Eenvoudiger alternatief: ${m[1]} overstappen · aankomst ~${m[2]}`],
 [/^No departures for this selection in the next (4|24) hours\.$/i,m=>`Geen vertrekken voor deze selectie in de komende ${m[1]} uur.`],
 [/^View full timetable \((\d+) departures\)$/i,m=>`Volledige dienstregeling bekijken (${m[1]} vertrekken)`],
 [/^Resend code in (\d+)s$/i,m=>`Code opnieuw versturen over ${m[1]} s`],
 [/^(using downloaded timetable|timetable downloaded)( \d{4}-\d{2}-\d{2})?\.?$/i,m=>t(m[1])+(m[2]||'')+(m[0].endsWith('.')?'.':'')],
 [/^Search covers (the 4 hours before arrival|the next 4 hours), up to two transfers and stops within 800 m of each endpoint\. Try a different time or nearby point\.$/i,m=>`De zoekopdracht omvat ${m[1]==='the next 4 hours'?'de komende 4 uur':'de 4 uur vóór aankomst'}, maximaal twee overstappen en haltes binnen 800 m van elk eindpunt. Probeer een andere tijd of een locatie in de buurt.`],
 [/^Choose a valid (future )?date and time in (.+?)\.(.*)$/i,m=>`Kies een geldige ${m[1]?'toekomstige ':''}datum en tijd in ${m[2]}.${m[3]?' Tijden die door de klokwisseling vervallen, zijn niet beschikbaar.':''}`],
 [/^Times are in (.+)\.$/i,m=>`Tijden zijn in de tijdzone ${m[1]}.`],
 [/^Live estimates where available · (.+)$/i,m=>`Actuele schattingen waar beschikbaar · ${m[1]}`],
];
const sentences=[...lookup.keys()].filter(k=>/[.!?]$/.test(k)).sort((a,b)=>b.length-a.length);
export function translateDutch(text){
 const input=text.trim();if(!input)return text;let output=dutchMessages[input]||lookup.get(input.toLowerCase());
 if(output===undefined)for(const [pattern,format] of rules){const m=input.match(pattern);if(m){output=format(m);break;}}
 if(output===undefined){const prefix=sentences.find(k=>input.toLowerCase().startsWith(k+' '));if(prefix)output=lookup.get(prefix)+translateDutch(input.slice(prefix.length));}
 if(output===undefined){const fragments=input.split(/(\s*·\s*|(?<=[.!?])\s+(?=[\p{Lu}]))/u);if(fragments.length>1)output=fragments.map((f,i)=>i%2?f:translateDutch(f)).join('');else if(/^[☆✓♿]\s*/u.test(input))output=input.replace(/^([☆✓♿]\s*)(.*)$/u,(_,p,b)=>p+translateDutch(b));else if(input.endsWith('.')&&lookup.has(input.slice(0,-1).toLowerCase()))output=t(input.slice(0,-1))+'.';else output=input;}
 return text.slice(0,text.indexOf(input))+output+text.slice(text.indexOf(input)+input.length);
}
